import{_ as r,l,o as e,c as n,v as t,p,x as o,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"分层编译","description":"","frontmatter":{"title":"分层编译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tiered-compilation.md","filePath":"cs/tiered-compilation.md","lastUpdated":1789023840000}'),h={name:"cs/tiered-compilation.md"};function m(_,a,C,u,T,f){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="分层编译" tabindex="-1">分层编译 <a class="header-anchor" href="#分层编译" aria-label="Permalink to &quot;分层编译&quot;">​</a></h1><div class="epigraph"><p>第一层快而笨（解释器或基线 JIT），高层慢而狠（优化 JIT）。热点升层，冷代码不付顶级编译的代价。</p><footer>—— 据 Paleczny, Vick and Click, The Java HotSpot Server Compiler；HotSpot 分层编译说明整理</footer></div><p>上一课<a href="/cs/type-feedback">类型反馈</a> 在各层都可收集。缺口是<strong>多层</strong>：解释器 / C1 / C2（HotSpot 名）。基线：几乎不优化，生成快，插满 profile。C2：内联、逃逸、循环，贵。本课钉升层策略，JIT 逃逸下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只用 C2：启动慢。只用解释器：峰值差。分层：阈值 1 进 C1，更高进 C2。去优化可降回 C1。缺口是<strong>编译预算队列</strong>，不是单层方法 JIT。</p><p>代码缓存：高层码更大，挤掉冷码。</p><h3 id="层不是「cpu-特权环」" tabindex="-1">层不是「CPU 特权环」 <a class="header-anchor" href="#层不是「cpu-特权环」" aria-label="Permalink to &quot;层不是「CPU 特权环」&quot;">​</a></h3><p>Ring 0 是硬件；compilation tier 是 VM 策略。不要混。</p><p><span class="marginnote">HotSpot 论文与博客。Graal 作为另一顶层点名。本课策略，不写 C2 所有遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每层入口、OSR 入口。计数跨层继承或再收集。后台编译：应用继续在旧层跑，完成后原子换入口。</p>',11)),(e(),p(c,null,{default:o(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20L0%5B%22%E8%A7%A3%E9%87%8A%E5%99%A8%22%5D%20--%3E%20L1%5B%22%E5%9F%BA%E7%BA%BF%20JIT%22%5D%0A%20%20L1%20--%3E%20L2%5B%22%E4%BC%98%E5%8C%96%20JIT%22%5D%0A%20%20L2%20--%3E%20DEOPT%5B%22%E5%8E%BB%E4%BC%98%E5%8C%96%E5%8F%AF%E9%99%8D%E5%B1%82%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与 PGO AOT：Graal Native Image 等把顶层提前，启动快峰值固定——点名对照，本课以在线分层为主。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>栈上有混合帧：C2 调 C1 调解释器。deopt 要认各层映射。不要死锁：编译线程要内存，应用线程要 CPU。</p><p>启发：平凡方法永不升 C2。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写逃逸算法。后课默认：VM 用分层摊还。下一课 JIT 中的逃逸分析：顶层优化之一。</p><p>也不把分层当微服务分层。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分层：快编译与狠优化分成多层，按热度升。</li><li>去优化可降层；代码缓存有限。</li><li>反馈在低层收集供给高层。</li><li>出处：Paleczny, Vick and Click；HotSpot 分层文档。</li></ul>',9))])}const A=r(h,[["render",m]]);export{P as __pageData,A as default};
